import fs from 'fs';
import { z } from 'zod';
import { installationChannel } from '../install/installationChannel';
import type { ProjectRegistry, RegisteredProject } from './ProjectRegistry';
import { LibraryError } from './libraryErrors';
import { readHandshake, isPidAlive } from '../cli/serverHandshake';
import { parseCommandContext, isCommandResult } from '../cli/commands/shared';
import {
  serverUnavailableReasonForEnvelope,
  type ServerUnavailableReason,
} from '../cli/telemetry';

interface ProjectRuntime {
  editorUrl: string;
}
const HEALTH_TIMEOUT_MS = 2_000;

export class ProjectRuntimeUnavailable extends Error {
  readonly serverUnavailableReason?: ServerUnavailableReason;
  constructor({
    message,
    serverUnavailableReason,
  }: {
    message: string;
    serverUnavailableReason?: ServerUnavailableReason;
  }) {
    super(message);
    this.name = 'ProjectRuntimeUnavailable';
    this.serverUnavailableReason = serverUnavailableReason;
  }
}

export class ProjectRuntimeService {
  private readonly activations = new Map<string, Promise<ProjectRuntime>>();
  constructor(private readonly registry: ProjectRegistry) {}

  async originalPreviewUrl(projectId: string): Promise<string | null> {
    const project = this.registry.get(projectId);
    if (!project.isAvailable) return null;
    const handshake = readHandshake(project.projectPath);
    if (!handshake || !isPidAlive(handshake.pid)) return null;
    const origin = `http://127.0.0.1:${handshake.rivetPort}`;
    try {
      const response = await fetch(`${origin}/api/health`, {
        signal: AbortSignal.timeout(HEALTH_TIMEOUT_MS),
      });
      if (!response.ok) return null;
      const health = z
        .object({
          projectPath: z.string(),
          pid: z.number().int(),
          channel: z.string(),
          originalPreviewPath: z
            .enum(['/static/', '/__rivet/preview/base/'])
            .nullish(),
        })
        .parse(await response.json());
      if (
        health.pid !== handshake.pid ||
        health.channel !== installationChannel() ||
        fs.realpathSync(health.projectPath) !== project.projectPath ||
        !health.originalPreviewPath
      )
        return null;
      return new URL(health.originalPreviewPath, origin).toString();
    } catch {
      return null;
    }
  }

  activate(projectId: string): Promise<ProjectRuntime> {
    const project = this.registry.get(projectId);
    if (!project.isAvailable)
      throw new LibraryError(
        'workspace_unavailable',
        'Relink this project to its working folder before editing.',
      );
    const pending = this.activations.get(project.id);
    if (pending) return pending;
    const activation = this.open(project);
    this.activations.set(project.id, activation);
    void activation
      .finally(() => this.activations.delete(project.id))
      .catch(() => {});
    return activation;
  }

  private async open(project: RegisteredProject): Promise<ProjectRuntime> {
    const { ensureProjectRuntime } = await import('../cli/commands/open');
    const context = parseCommandContext('open', [
      '--project',
      project.projectPath,
      ...(process.env.RIVET_LIBRARY_TELEMETRY === '0'
        ? ['--no-telemetry']
        : []),
    ]);
    if (isCommandResult(context)) {
      if (!context.envelope.ok) throw new Error(context.envelope.error.message);
      throw new Error('Could not resolve project runtime context');
    }
    const result = await ensureProjectRuntime(context, {
      writeProgress: () => {},
      writeEnvelope: () => {},
    });
    if (!result.envelope.ok)
      throw new ProjectRuntimeUnavailable({
        message: result.envelope.error.message,
        serverUnavailableReason: serverUnavailableReasonForEnvelope(
          result.envelope,
        ),
      });
    const data = z
      .object({ editorUrl: z.string().url() })
      .parse(result.envelope.data);
    const response = await fetch(new URL('/api/health', data.editorUrl), {
      signal: AbortSignal.timeout(HEALTH_TIMEOUT_MS),
    });
    const health = z
      .object({
        projectPath: z.string(),
        pid: z.number().int(),
        channel: z.string(),
      })
      .parse(await response.json());
    const { readHandshake } = await import('../cli/serverHandshake');
    const handshake = readHandshake(project.projectPath);
    if (
      !response.ok ||
      !handshake ||
      health.pid !== handshake.pid ||
      fs.realpathSync(health.projectPath) !== project.projectPath ||
      health.channel !== installationChannel()
    )
      throw new Error(
        'The project runtime could not verify its identity. Keep current work running and reopen after it finishes.',
      );
    return data;
  }
}
